const instance = WebViewer.getInstance(); 

const { Core: { documentViewer, annotationManager, PDFNet } } = instance;
async function extractFirstThreeLines() {
  try {
    await PDFNet.initialize();

    const doc = documentViewer.getDocument();

    if (!doc) {
      console.log('No document loaded');
      return;
    }

    const pdfDoc = await doc.getPDFDoc();

    if (!pdfDoc) {
      console.log('Document is not a PDF');
      return;
    }

    const txt = await PDFNet.runWithCleanup(async () => {
      const textExtractor = await PDFNet.TextExtractor.create();

      const firstPage = await pdfDoc.getPage(1);
      await textExtractor.begin(firstPage, null);

      const fullText = await textExtractor.getAsText();

      const lines = fullText.split('
');
      const firstThreeLines = lines.slice(0, 3).join('
');

      return firstThreeLines;
    });

    return txt;

  } catch (error) {
    console.error('Error extracting text:', error);
  }
}

extractFirstThreeLines();

