const findText = (searchTerm, pg = 1) => {
  return new Promise((resolve) => {
    const searchListener = (searchPattern, options, results) => {
      UI.removeSearchListener(searchListener);

      const page1Results = results.filter(result => result.page_num === pg);

      const textRects = page1Results.map(result => {
        const q = result.quads[0];

        const topY = q.y1;
        const bottomY = q.pm || q.va;

        return {
          x: q.x1,                   
          y: topY,                   
          width: q.x2 - q.x1,         
          height: bottomY - topY    
        };
      });

      resolve(textRects);
    };

    UI.addSearchListener(searchListener);
    UI.searchTextFull(searchTerm, { 
      pageNumber: pg,
      ambientString: true 
    });
  });
};

