(function () {
  function ensureOverlayContainer() {
    const viewerEl = document.getElementById('viewer') || document.querySelector('#viewer');
    if (!viewerEl) {
      console.error('Viewer element not found (expected #viewer).');
      return null;
    }

    let overlay = document.getElementById('wv-left-indicator-overlay');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'wv-left-indicator-overlay';
      Object.assign(overlay.style, {
        position: 'absolute',
        pointerEvents: 'none',
        zIndex: 9999
      });
      document.body.appendChild(overlay);

      syncOverlayToViewer();
      window.addEventListener('resize', syncOverlayToViewer);
      window.addEventListener('scroll', syncOverlayToViewer);
    }
    return overlay;
  }

  function syncOverlayToViewer() {
    const viewerEl = document.getElementById('viewer') || document.querySelector('#viewer');
    const overlay = document.getElementById('wv-left-indicator-overlay');
    if (!viewerEl || !overlay) return;

    const rect = viewerEl.getBoundingClientRect();
    overlay.style.top = rect.top + window.scrollY + 'px';
    overlay.style.left = rect.left + window.scrollX + 'px';
    overlay.style.width = rect.width + 'px';
    overlay.style.height = rect.height + 'px';
  }

  window.addLeftOverlayIndicator = function (yOffset, text) {
    const overlay = ensureOverlayContainer();
    if (!overlay) return;

    const WIDTH = 160;     

    const wrapper = document.createElement('div');
    Object.assign(wrapper.style, {
      position: 'absolute',
      left: '0px',
      top: `${yOffset}px`, 
      pointerEvents: 'none',
      width: `${WIDTH}px`,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start'
    });

    const ARROW_HEIGHT = 18;
    const ARROW_WIDTH = 26;

    const arrow = document.createElement('div');
    Object.assign(arrow.style, {
      width: '0',
      height: '0',
      borderTop: `${ARROW_HEIGHT / 2}px solid transparent`,
      borderBottom: `${ARROW_HEIGHT / 2}px solid transparent`,
      borderLeft: `${ARROW_WIDTH}px solid #001f3f`,
      marginBottom: '2px'  
    });

    const PADDING_V = 4;  
    const PADDING_H = 8;

    const box = document.createElement('div');
    box.textContent = text;
    Object.assign(box.style, {
      backgroundColor: 'white',
      color: '#001f3f',
      fontFamily: 'sans-serif',
      fontSize: '12px',
      padding: `${PADDING_V}px ${PADDING_H}px`,
      border: '1px solid #001f3f',
      borderRadius: '0 4px 4px 0',
      boxSizing: 'border-box',
      maxWidth: `${WIDTH}px`,
      whiteSpace: 'normal',
      wordBreak: 'break-word',
      pointerEvents: 'none'
    });

    wrapper.appendChild(arrow);
    wrapper.appendChild(box);
    overlay.appendChild(wrapper);

    return wrapper;
  };

  window.syncLeftOverlayIndicators = syncOverlayToViewer;
})();
